1import Header from "./components/Header";
2import EntryCard from "./components/EntryCard";
3import JournalForm from "./components/JournalForm";
4
5function App() {
6  const entry = {
7    title: "First Day at the Job",
8    date: "February 10, 2026",
9    content: "Today was my first day at the new job. Everyone was welcoming and helpful."
10  };
11
12  return (
13    <div className="main-container">
14     <Header />
15      <JournalForm />
16      <EntryCard 
17        title={entry.title}
18        date={entry.date}
19        content={entry.content}
20      />
21    </div>
22  );
23}
24
25export default App;

1function Header() {
2  return (
3    <header className="header">
4      <h2 className="title-primary">My Daily Journal</h2>
5      <p className="subtitle">Capture your thoughts, one day at a time.</p>
6    </header>
7  );
8}
9
10export default Header;

1function EntryCard({ title, date, content }) {
2  return (
3    <div className="entry-item">
4    <div className="entry-date">{date}</div>
5      <h2 className="entry-title">{title}</h2>
6      <p className="entry-content">{content}</p>
7    </div>
8  );
9}
10
11export default EntryCard;

1function JournalForm() {
2  return (
3    <section className="card">
4      <form>
5          <input 
6            id="title" 
7            type="text" 
8            placeholder="Entry title"
9            className="input-field"
10          /> 
11          <textarea 
12            id="content" 
13            placeholder="What's on your mind?"
14            className="textarea-field"
15            rows={4}
16         />
17        <button className="btn btn-primary">Add Entry</button>
18      </form>
19    </section>
20  );
21}
22
23export default JournalForm;
24:root {
