192  padding: 0.625rem 1.25rem;
193  font-size: 0.875rem;
194  font-weight: 500;
195  border-radius: var(--radius-lg);
196  cursor: pointer;
197  transition: all 0.2s;
198  border: none;
199}
200
201.btn-primary {
202  background-color: var(--primary);
